WITH unpacked AS (SELECT id, effective_from, currency, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency = 'USD') SELECT id, effective_from, currency, entry_price, MIN(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_entry_price, AVG(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_entry_price, MAX(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_entry_price, COUNT(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_entry_price FROM unpacked WHERE avg_tier_price > 18;
